$ErrorActionPreference = 'Stop'
$Target = Join-Path $env:USERPROFILE 'Desktop\중국판매데이터RAW\desktop_app'
if ($args.Count -gt 0) { $Target = $args[0] }
$files = @{
  'wj_app.py' = ''
  'README.md' = ''
  'requirements.txt' = 'cHl3ZWJ2aWV3Pj01LjAK'
  'build_exe.ps1' = ''
}
New-Item -ItemType Directory -Force -Path $Target | Out-Null
foreach ($name in $files.Keys) {
  $path = Join-Path $Target $name
  if (Test-Path $path) { Copy-Item $path ($path + '.bak') -Force }
  [System.IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($files[$name]))
  Write-Host ('저장: ' + $path)
}
Write-Host ''
Write-Host '완료. 다음 순서로 실행하세요:'
Write-Host ('  cd "' + $Target + '"')
Write-Host '  pip install -r requirements.txt'
Write-Host '  python wj_app.py --browser'
